function passwordStrength(pw) {
  if (!pw) return { score: 0, label: "", tint: C.border };
  let score = 0;
  if (pw.length >= 6) score++;
  if (pw.length >= 10) score++;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) score++;
  if (/[0-9]/.test(pw)) score++;
  if (/[^A-Za-z0-9]/.test(pw)) score++;
  const levels = [
    { label: "ضعيفة", tint: C.ember }, { label: "ضعيفة", tint: C.ember },
    { label: "متوسطة", tint: C.amber }, { label: "جيدة", tint: C.blueBright },
    { label: "قوية", tint: C.green }, { label: "قوية جدًا", tint: C.green },
  ];
  return { score, ...levels[Math.min(score, 5)] };
}
function isValidEmail(v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }
function isValidPhone(v) { return /^0[5-7][0-9]{8}$/.test(v.replace(/\s/g, "")); }

