/* =========================================================================
   APP SHELL — bottom nav (mobile) / sidebar (desktop), top bar with
   search + notifications + profile, page-transition wrapper.
   ========================================================================= */
function Shell({ ctx, children }) {
  const { session, setSession, setView, viewport, view, unreadNotifs } = ctx;
  const items = navFor(session.role);
  const isMobile = viewport === "mobile";

  function logout() { sbSignOut(); setSession(null); setView("splash"); }

  const topBar = (
    <div style={{
      position: "sticky", top: 0, zIndex: 20, background: "rgba(255,255,255,.92)", backdropFilter: "blur(8px)",
      borderBottom: `1px solid ${C.borderSoft}`, padding: "14px 18px", display: "flex", alignItems: "center", gap: 12,
    }}>
      {!isMobile && <div style={{ display: "flex", alignItems: "center", gap: 9, marginInlineEnd: 6 }}><Logomark size={26} /><span style={{ fontWeight: 800, fontFamily: DISPLAY, fontSize: 15 }}>StaySober</span></div>}
      <button onClick={() => setView("search")} className="ss-press" style={{
        flex: 1, display: "flex", alignItems: "center", gap: 8, background: C.bgSoft, border: `1px solid ${C.border}`,
        borderRadius: 100, padding: "10px 16px", color: C.textFaint, fontSize: 13, cursor: "pointer", fontFamily: FONT,
      }}><Search size={15} /> ابحث عن مختص، دورة، بودكاست…</button>
      <IconBtn icon={Bell} tone={unreadNotifs > 0 ? "blue" : "ghost"} onClick={() => setView("notifications")} />
      <button onClick={() => setView("profile")} className="ss-press" style={{ background: "none", border: "none", cursor: "pointer", padding: 0 }}>
        <Avatar name={session.name} size={36} verified={session.verified} />
      </button>
    </div>
  );

  const content = (
    <div style={{ flex: 1, minWidth: 0, overflowY: "auto", height: "100vh" }}>
      {topBar}
      <OfflineBanner />
      <div key={view} className="ss-fadeUp" style={{ maxWidth: 900, margin: "0 auto", padding: isMobile ? "18px 16px 100px" : "26px 34px 60px" }}>
        {children}
      </div>
    </div>
  );

  if (isMobile) {
    return (
      <div style={{ display: "flex", flexDirection: "column", height: "100vh", background: C.bg }}>
        {content}
        <div style={{
          position: "fixed", bottom: 0, insetInline: 0, background: "rgba(255,255,255,.95)", backdropFilter: "blur(10px)",
          borderTop: `1px solid ${C.borderSoft}`, display: "flex", justifyContent: "space-around", padding: "8px 4px calc(8px + env(safe-area-inset-bottom))", zIndex: 30,
        }}>
          {items.map((it) => {
            const active = view === it.id;
            return (
              <button key={it.id} onClick={() => setView(it.id)} className="ss-press" style={{
                background: "none", border: "none", display: "flex", flexDirection: "column", alignItems: "center", gap: 3,
                color: active ? C.blue : C.textFaint, fontSize: 10, fontWeight: 700, cursor: "pointer", padding: "4px 10px", position: "relative",
              }}>
                <it.icon size={20} strokeWidth={active ? 2.4 : 2} />
                {it.label}
                {active && <div style={{ position: "absolute", top: -8, width: 4, height: 4, borderRadius: "50%", background: C.blue }} />}
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", background: C.bg }}>
      <div style={{ width: 224, flex: "none", background: "#fff", height: "100vh", borderInlineEnd: `1px solid ${C.borderSoft}`, padding: "20px 14px", display: "flex", flexDirection: "column" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 28, padding: "0 8px" }}>
          <Logomark size={32} /><span style={{ fontWeight: 800, fontFamily: DISPLAY, fontSize: 16 }}>StaySober</span>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 2, flex: 1 }}>
          {items.map((it) => {
            const active = view === it.id;
            return (
              <button key={it.id} onClick={() => setView(it.id)} className="ss-press" style={{
                background: active ? C.blueSoft : "transparent", border: "none", textAlign: "right",
                color: active ? C.blue : C.textDim, fontWeight: 700, fontSize: 13.5, padding: "11px 14px",
                borderRadius: 12, cursor: "pointer", display: "flex", alignItems: "center", gap: 11, transition: "background .15s",
              }} onMouseEnter={(e) => { if (!active) e.currentTarget.style.background = C.bgSofter; }}
                 onMouseLeave={(e) => { if (!active) e.currentTarget.style.background = "transparent"; }}>
                <it.icon size={18} strokeWidth={active ? 2.4 : 2} />{it.label}
              </button>
            );
          })}
        </div>
        <button onClick={() => setView("settings")} className="ss-press" style={{ background: "none", border: "none", textAlign: "right", color: C.textDim, fontSize: 13, padding: "10px 14px", cursor: "pointer", display: "flex", alignItems: "center", gap: 11 }}>
          <Settings size={17} /> الإعدادات
        </button>
        <button onClick={logout} className="ss-press" style={{ background: "none", border: "none", textAlign: "right", color: C.textFaint, fontSize: 12.5, padding: "10px 14px", cursor: "pointer", display: "flex", alignItems: "center", gap: 11 }}>
          <LogOut size={16} /> تسجيل الخروج
        </button>
      </div>
      {content}
    </div>
  );
}

