function Accordion({ items }) {
  const [open, setOpen] = useState(0);
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      {items.map((it, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.border}`, borderRadius: 16, overflow: "hidden" }}>
          <button onClick={() => setOpen(open === i ? -1 : i)} className="ss-press" style={{ all: "unset", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 18px", width: "100%", boxSizing: "border-box" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5 }}>{it.q}</span>
            <ChevronDown size={17} color={C.textDim} style={{ transform: open === i ? "rotate(180deg)" : "none", transition: ".2s", flex: "none" }} />
          </button>
          {open === i && <div className="ss-fadeUp" style={{ padding: "0 18px 18px", fontSize: 12.5, color: C.textDim, lineHeight: 1.85 }}>{it.a}</div>}
        </div>
      ))}
    </div>
  );
}

function NewsletterBandForm({ ctx, isMobile }) {
  const [email, setEmail] = useState("");
  const [subscribed, setSubscribed] = useState(false);
  function subscribe() {
    if (!isValidEmail(email)) { ctx.toast("أدخل بريدًا إلكترونيًا صحيحًا", "error"); return; }
    setSubscribed(true);
    ctx.toast("تم الاشتراك في النشرة ✓");
  }
  if (subscribed) return <Pill tone="green" icon={CheckCircle2}>أنت مشترك الآن</Pill>;
  return (
    <div style={{ display: "flex", gap: 8, width: isMobile ? "100%" : "auto" }}>
      <input value={email} onChange={(e) => setEmail(e.target.value)} onKeyDown={(e) => e.key === "Enter" && subscribe()} placeholder="بريدك الإلكتروني" style={{ flex: 1, minWidth: isMobile ? 0 : 220, borderRadius: 100, border: `1.4px solid ${C.border}`, padding: "12px 16px", fontSize: 13, fontFamily: FONT, boxSizing: "border-box" }} />
      <Btn onClick={subscribe}>اشترك</Btn>
    </div>
  );
}
function NewsletterForm({ ctx }) {
  const [email, setEmail] = useState("");
  const [subscribed, setSubscribed] = useState(false);
  function subscribe() {
    if (!isValidEmail(email)) { ctx.toast("أدخل بريدًا إلكترونيًا صحيحًا", "error"); return; }
    setSubscribed(true);
    ctx.toast("تم الاشتراك في النشرة ✓");
  }
  if (subscribed) return <div style={{ fontSize: 11.5, color: "#BFE9E1", marginBottom: 16 }}>✓ أنت مشترك الآن، شكرًا لك</div>;
  return (
    <div style={{ display: "flex", gap: 6, marginBottom: 16 }}>
      <input value={email} onChange={(e) => setEmail(e.target.value)} onKeyDown={(e) => e.key === "Enter" && subscribe()} placeholder="بريدك الإلكتروني" style={{ flex: 1, borderRadius: 100, border: "none", padding: "9px 14px", fontSize: 11.5, fontFamily: FONT }} />
      <IconBtn icon={ArrowLeft} tone="white" size={36} onClick={subscribe} />
    </div>
  );
}
