function AdminUsersScreen({ ctx }) {
  const [rows, setRows] = useState(ctx.users.slice(0, 6));
  const [loading, setLoading] = useState(true);
  const [menuOpenId, setMenuOpenId] = useState(null);
  useEffect(() => {
    (async () => {
      try {
        const real = await sbSelect("users", { select: "id,full_name,role,is_active", order: "created_at.desc", limit: 50 });
        if (real.length) setRows(real.map((r) => ({ id: r.id, name: r.full_name, role: DB_ROLE_TO_APP_ROLE[r.role] || r.role, isActive: r.is_active })));
      } catch (err) { console.error("admin users load failed:", err.message); }
      finally { setLoading(false); }
    })();
  }, []);
  async function toggleActive(u) {
    setMenuOpenId(null);
    const nextActive = !u.isActive;
    setRows((prev) => prev.map((r) => (r.id === u.id ? { ...r, isActive: nextActive } : r)));
    try {
      await sbUpdate("users", { id: u.id }, { is_active: nextActive });
      ctx.toast(nextActive ? "تم تفعيل الحساب" : "تم تعطيل الحساب", "info");
    } catch (err) {
      setRows((prev) => prev.map((r) => (r.id === u.id ? { ...r, isActive: !nextActive } : r))); // roll back
      ctx.toast(err.message || "تعذّر تحديث حالة الحساب", "error");
    }
  }
  return (
    <div>
      <ScreenHeader eyebrow="إدارة" title="المستخدمون" action={<Btn size="sm" icon={Plus} onClick={() => ctx.toast("إضافة مستخدم يدويًا من لوحة الإدارة قيد التطوير — استخدمي التسجيل العادي حاليًا", "info")}>إضافة</Btn>} />
      {loading ? <SkeletonCard /> : rows.length === 0 ? (
        <EmptyState icon={Users} title="لا يوجد مستخدمون بعد" />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {rows.map((u, i) => (
            <Card key={u.id || i} style={{ display: "flex", alignItems: "center", gap: 12, position: "relative", opacity: u.isActive === false ? 0.55 : 1 }}>
              <Avatar name={u.name} size={38} />
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, fontSize: 12.5 }}>{u.name}</div>
                <div style={{ fontSize: 10.5, color: C.textDim }}>{CATEGORY_MAP[u.role]?.label || u.role}{u.isActive === false ? " · معطَّل" : ""}</div>
              </div>
              <IconBtn icon={MoreHorizontal} size={30} onClick={() => setMenuOpenId(menuOpenId === u.id ? null : u.id)} />
              {menuOpenId === u.id && (
                <div className="ss-scaleIn" style={{ position: "absolute", left: 10, top: 44, background: "#fff", border: `1px solid ${C.border}`, borderRadius: 12, boxShadow: C.shadowLg, zIndex: 10, minWidth: 150, overflow: "hidden" }}>
                  <button onClick={() => toggleActive(u)} className="ss-press" style={{ all: "unset", cursor: "pointer", display: "flex", alignItems: "center", gap: 8, padding: "10px 14px", fontSize: 12, width: "100%", boxSizing: "border-box", color: u.isActive === false ? C.green : C.ember }}>
                    {u.isActive === false ? <CheckCircle2 size={13} /> : <XCircle size={13} />}
                    {u.isActive === false ? "تفعيل الحساب" : "تعطيل الحساب"}
                  </button>
                </div>
              )}
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
