/* =========================================================================
   CALENDAR
   ========================================================================= */
function CalendarScreen({ ctx }) {
  const [mode, setMode] = useState("week");
  const dayNames = ["أحد", "إثنين", "ثلاثاء", "أربعاء", "خميس", "جمعة", "سبت"];
  const weekStart = useMemo(() => { const d = new Date(); d.setDate(d.getDate() - d.getDay()); d.setHours(0, 0, 0, 0); return d; }, []);
  const weekDates = useMemo(() => Array.from({ length: 7 }, (_, i) => { const d = new Date(weekStart); d.setDate(d.getDate() + i); return d; }), [weekStart]);
  const [events, setEvents] = useState({ 1: [{ t: "10:00", l: "جلسة نفسية", tint: C.purple }], 3: [{ t: "17:00", l: "تمرين رياضي", tint: C.amber }], 4: [{ t: "12:00", l: "درس Excel", tint: C.blue }, { t: "19:00", l: "تذكير: تناول الدواء", tint: C.green }] });

  useEffect(() => {
    (async () => {
      try {
        const isSpecialist = PROVIDER_CATS.includes(ctx.session.role);
        const filterKey = isSpecialist ? "specialist_id" : "patient_id";
        const otherField = isSpecialist ? "users!appointments_patient_id_fkey(full_name)" : "users!appointments_specialist_id_fkey(full_name)";
        const rows = await sbSelect("appointments", {
          select: `id,scheduled_at,consultation_type,${otherField}`,
          filters: { [filterKey]: ctx.session.id },
        });
        const weekEnd = new Date(weekStart); weekEnd.setDate(weekEnd.getDate() + 7);
        const inWeek = rows.filter((r) => { const d = new Date(r.scheduled_at); return d >= weekStart && d < weekEnd; });
        if (!inWeek.length) return;
        const grouped = {};
        inWeek.forEach((r) => {
          const d = new Date(r.scheduled_at);
          const idx = d.getDay();
          const name = r.users?.full_name || "موعد";
          (grouped[idx] ||= []).push({ t: d.toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" }), l: `${name} — ${r.consultation_type === "video" ? "فيديو" : "حضوري"}`, tint: C.blue });
        });
        setEvents(grouped);
      } catch (err) { console.error("calendar load failed:", err.message); }
    })();
  }, [weekStart]);

  return (
    <div>
      <ScreenHeader eyebrow="التنظيم" title="التقويم" action={
        <div style={{ display: "flex", gap: 6 }}>{["يوم", "أسبوع", "شهر"].map((m, i) => <button key={m} onClick={() => setMode(m)} className="ss-press" style={{ border: "none", borderRadius: 100, padding: "6px 12px", fontSize: 11, cursor: "pointer", background: mode === m ? C.blue : C.bgSofter, color: mode === m ? "#fff" : C.textDim, fontWeight: 700, fontFamily: FONT }}>{m}</button>)}</div>
      } />
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {mode === "شهر" && (
          <Card style={{ background: C.blueSoft, border: "none", marginBottom: 4 }}>
            <div style={{ fontSize: 11.5, color: C.blueDeep }}>عرض الشهر الكامل قيد التطوير — يُعرض الأسبوع الحالي أدناه في الوقت الحالي.</div>
          </Card>
        )}
        {dayNames.map((d, i) => {
          const isToday = weekDates[i].toDateString() === new Date().toDateString();
          if (mode === "يوم" && !isToday) return null;
          return (
          <Card key={d} style={{ display: "flex", gap: 14 }}>
            <div style={{ width: 40, textAlign: "center", flex: "none" }}>
              <div style={{ fontSize: 10.5, color: C.textDim, fontWeight: 700 }}>{d}</div>
              <div style={{ fontSize: 15, fontWeight: 800, fontFamily: DISPLAY, color: isToday ? C.blue : C.text }}>{weekDates[i].getDate()}</div>
            </div>
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 6 }}>
              {(events[i] || []).map((e, j) => (
                <div key={j} style={{ display: "flex", alignItems: "center", gap: 8, background: `${e.tint}10`, borderRight: `3px solid ${e.tint}`, borderRadius: 8, padding: "7px 10px" }}>
                  <span style={{ fontSize: 11, fontWeight: 800, color: e.tint, fontFamily: DISPLAY }}>{e.t}</span><span style={{ fontSize: 11.5 }}>{e.l}</span>
                </div>
              ))}
              {!(events[i] || []).length && <div style={{ fontSize: 11, color: C.textFaint }}>لا أحداث</div>}
            </div>
          </Card>
          );
        })}
      </div>
    </div>
  );
}

/* =========================================================================
   CRISIS — critical safety screen (carried over from the previous build)
   ========================================================================= */
function VideoCallScreen({ ctx }) {
  const [phase, setPhase] = useState("waiting"); // waiting | connected | failed | ended
  const [muted, setMuted] = useState(false);
  const [camOff, setCamOff] = useState(false);
  const [seconds, setSeconds] = useState(0);
  const [quality, setQuality] = useState("جيدة");
  const [attempt, setAttempt] = useState(0);
  const [sessionRowId, setSessionRowId] = useState(null);
  const realAppointmentId = ctx.activeAppointment?.id;
  const looksLikeUuid = realAppointmentId && /^[0-9a-f-]{36}$/i.test(realAppointmentId);

  useEffect(() => {
    const t = setTimeout(() => setPhase(Math.random() < 0.2 && attempt === 0 ? "failed" : "connected"), 2600);
    return () => clearTimeout(t);
  }, [attempt]);
  useEffect(() => {
    if (phase !== "connected") return;
    const iv = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(iv);
  }, [phase]);
  useEffect(() => {
    if (phase !== "connected") return;
    const iv = setInterval(() => setQuality((q) => (Math.random() > 0.85 ? "متوسطة" : "جيدة")), 6000);
    return () => clearInterval(iv);
  }, [phase]);
  useEffect(() => {
    if (phase !== "connected" || !looksLikeUuid || sessionRowId) return;
    (async () => {
      try {
        const [row] = await sbInsert("video_sessions", [{ appointment_id: realAppointmentId, started_at: new Date().toISOString() }]);
        setSessionRowId(row.id);
      } catch (err) { console.error("video_sessions insert failed:", err.message); ctx.toast(err.message || "تعذّر تسجيل بيانات الجلسة", "error"); }
    })();
  }, [phase]);
  useEffect(() => {
    if (phase !== "ended" || !sessionRowId) return;
    sbUpdate("video_sessions", { id: sessionRowId }, {
      ended_at: new Date().toISOString(), duration_seconds: seconds, ended_reason: "completed",
      avg_connection_quality: quality === "جيدة" ? "good" : "fair",
    }).catch((err) => console.error("video_sessions update failed:", err.message));
  }, [phase]);

  const mm = String(Math.floor(seconds / 60)).padStart(2, "0");
  const ss = String(seconds % 60).padStart(2, "0");

  if (phase === "failed") {
    return (
      <div style={{ minHeight: "100vh", background: "#12181C", display: "flex", alignItems: "center", justifyContent: "center", padding: 24, color: "#fff" }}>
        <div className="ss-scaleIn" style={{ textAlign: "center", maxWidth: 340 }}>
          <div style={{ width: 78, height: 78, borderRadius: "50%", background: "rgba(222,91,59,.15)", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 18px" }}>
            <WifiOff size={32} color={C.ember} />
          </div>
          <div style={{ fontFamily: DISPLAY, fontWeight: 800, fontSize: 17, marginBottom: 8 }}>تعذّر الاتصال</div>
          <div style={{ fontSize: 12.5, color: "#B7C1C8", lineHeight: 1.8, marginBottom: 22 }}>
            لم نتمكن من إنشاء اتصال مرئي مستقر، غالبًا بسبب ضعف مؤقت في الشبكة. تحقق من اتصالك بالإنترنت وحاول مرة أخرى.
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <Btn full icon={RefreshCw} onClick={() => { setAttempt((a) => a + 1); setPhase("waiting"); }}>إعادة المحاولة</Btn>
            <Btn full variant="ghost" style={{ background: "rgba(255,255,255,.1)", color: "#fff" }} icon={MessageCircle} onClick={() => ctx.setView("chat")}>تواصل عبر الرسائل بدلًا من ذلك</Btn>
            <button onClick={() => ctx.setView("home")} style={{ background: "none", border: "none", color: "#8B98A3", padding: 10, cursor: "pointer", fontFamily: FONT, fontSize: 12.5 }}>العودة إلى الرئيسية</button>
          </div>
        </div>
      </div>
    );
  }

  if (phase === "ended") {
    return (
      <div style={{ minHeight: "100vh", background: C.bg, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
        <div className="ss-scaleIn" style={{ textAlign: "center", maxWidth: 340 }}>
          <div style={{ width: 78, height: 78, borderRadius: "50%", background: C.greenSoft, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 18px" }}>
            <CheckCircle2 size={34} color={C.green} />
          </div>
          <div style={{ fontFamily: DISPLAY, fontWeight: 800, fontSize: 17, marginBottom: 6 }}>انتهت الجلسة</div>
          <div style={{ fontSize: 12.5, color: C.textDim, marginBottom: 18 }}>مع د. هناء حسين · استمرت {mm}:{ss} دقيقة</div>
          <Card style={{ marginBottom: 18, textAlign: "start" }}>
            <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 10 }}>كيف كانت جودة الاتصال؟</div>
            <div style={{ display: "flex", gap: 8, justifyContent: "center" }}>
              {[1, 2, 3, 4, 5].map((n) => <Star key={n} size={22} color={C.amber} fill={C.amber} style={{ cursor: "pointer" }} />)}
            </div>
          </Card>
          <Btn full onClick={() => ctx.setView("home")}>العودة إلى الرئيسية</Btn>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "#12181C", display: "flex", flexDirection: "column", color: "#fff" }}>
      <div style={{ padding: "18px 20px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <Pill tone={quality === "جيدة" ? "green" : "amber"} icon={Activity}>اتصال {quality}</Pill>
        {phase === "connected" && <div style={{ fontFamily: DISPLAY, fontWeight: 700, fontSize: 14 }}>{mm}:{ss}</div>}
      </div>

      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
        {phase === "waiting" ? (
          <div className="ss-fadeUp" style={{ textAlign: "center" }}>
            <div className="ss-float" style={{ marginBottom: 18 }}><SpecialistPhoto name="د. هناء حسين" tint={C.purple} photo="/specialists/hanaa-hussein.jpg" size={96} verified /></div>
            <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 6 }}>بانتظار انضمام د. هناء حسين…</div>
            <div style={{ fontSize: 12, color: "#8B98A3" }}>سيبدأ الاتصال تلقائيًا فور دخولها</div>
          </div>
        ) : (
          <div className="ss-fade" style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", background: "linear-gradient(160deg, #1A2226, #0F1417)" }}>
            <SpecialistPhoto name="د. هناء حسين" tint={C.purple} photo="/specialists/hanaa-hussein.jpg" size={120} verified />
          </div>
        )}
        {/* self-view */}
        <div style={{ position: "absolute", bottom: 20, insetInlineEnd: 20, width: 90, height: 130, borderRadius: 16, background: "#1F2A2F", border: "1px solid rgba(255,255,255,.15)", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
          {camOff ? <User size={28} color="#5A6570" /> : <div style={{ width: "100%", height: "100%", background: "linear-gradient(160deg, #2A3238, #171D20)", display: "flex", alignItems: "center", justifyContent: "center" }}><User size={30} color="#4A5560" /></div>}
        </div>
      </div>

      <div style={{ padding: "24px 20px 40px", display: "flex", justifyContent: "center", gap: 16 }}>
        <IconBtn icon={muted ? MicOff : Mic} tone="white" size={52} onClick={() => setMuted(!muted)} />
        <IconBtn icon={camOff ? VideoOff : Video} tone="white" size={52} onClick={() => setCamOff(!camOff)} />
        <button onClick={() => setPhase("ended")} className="ss-press" style={{ all: "unset", cursor: "pointer", width: 62, height: 52, borderRadius: 26, background: C.ember, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Phone size={22} color="#fff" style={{ transform: "rotate(135deg)" }} />
        </button>
      </div>
    </div>
  );
}

function CrisisScreen({ ctx }) {
  useEffect(() => {
    ctx.addCrisisEvent({ id: uid(), patientId: ctx.session.id, patientName: ctx.session.name, createdAt: Date.now() });
    (async () => {
      try {
        await sbInsert("emergency_requests", [{ patient_id: ctx.session.id, action_taken: "helpline_call" }]);
      } catch (err) {
        console.error("emergency_requests insert failed:", err.message);
      }
    })();
  }, []);
  return (
    <div style={{ minHeight: "100vh", background: `linear-gradient(180deg, #9E3A22, #5C1A0E)`, color: "#fff", display: "flex", flexDirection: "column" }}>
      <div style={{ padding: "48px 26px 10px", textAlign: "center" }}>
        <div className="ss-float"><AlertTriangle size={40} color="#fff" /></div>
        <div style={{ fontSize: 13, color: "#F5CFC2", margin: "14px 0 6px" }}>أنت لست وحدك الآن</div>
        <div style={{ fontFamily: DISPLAY, fontWeight: 800, fontSize: 22 }}>نحن هنا معك</div>
        <p style={{ fontSize: 13, color: "#F5CFC2", lineHeight: 1.8, marginTop: 10 }}>خذ نفسًا عميقًا. هناك من يمكنه مساعدتك في هذه اللحظة بالذات.</p>
      </div>
      <div style={{ padding: 22, display: "flex", flexDirection: "column", gap: 12, flex: 1, maxWidth: 420, margin: "0 auto", width: "100%", boxSizing: "border-box" }}>
        <Btn full icon={Phone} style={{ background: "#fff", color: "#8F2A16", fontSize: 15.5, padding: 16 }} onClick={() => { window.location.href = "tel:3033"; }}>اتصل بخط المساعدة الآن — 3033</Btn>
        <Btn full icon={MessageCircle} style={{ background: "rgba(255,255,255,.14)", color: "#fff" }} onClick={() => ctx.setView("chat")}>تواصل فوري مع معالجك</Btn>
        <Btn full icon={Users} style={{ background: "rgba(255,255,255,.14)", color: "#fff" }} onClick={() => ctx.toast("سيتطلّب هذا رقم جهة اتصال طوارئ محفوظًا في إعداداتك أولًا", "info")}>أرسل تنبيهًا لشخص أثق به</Btn>
        <Card style={{ background: "rgba(255,255,255,.08)", border: "1px solid rgba(255,255,255,.2)", marginTop: 6 }}>
          <div style={{ fontWeight: 700, fontSize: 12.5, marginBottom: 8, color: "#fff" }}>تمرين تنفّس سريع (60 ثانية)</div>
          <div style={{ fontSize: 12, color: "#F5CFC2", lineHeight: 1.7 }}>شهيق 4 ثوانٍ ← حبس 4 ثوانٍ ← زفير 6 ثوانٍ. كرّرها 5 مرات.</div>
        </Card>
      </div>
      <button onClick={() => ctx.setView("home")} style={{ background: "none", border: "none", color: "#F5CFC2", padding: 18, cursor: "pointer", fontFamily: FONT }}>العودة إلى الصفحة الرئيسية</button>
    </div>
  );
}

/* =========================================================================
   CRAVING LOG
   ========================================================================= */
const CRAVING_TAGS = ["قلق", "وحدة", "ضغط اجتماعي", "أرق", "خلاف عائلي", "مكان مألوف"];
function CravingScreen({ ctx }) {
  const { session, cravingLogs, addCravingLog } = ctx;
  const [intensity, setIntensity] = useState(4);
  const [tags, setTags] = useState([]);
  const [recentLogs, setRecentLogs] = useState(null);
  const [loadingLogs, setLoadingLogs] = useState(true);
  function toggleTag(t) { setTags((p) => (p.includes(t) ? p.filter((x) => x !== t) : [...p, t])); }

  async function loadRecentLogs() {
    try {
      const rows = await sbSelect("mood_logs", {
        select: "id,logged_at,craving_intensity,triggers",
        filters: { patient_id: session.id },
        order: "logged_at.desc",
        limit: 10,
      });
      setRecentLogs(rows);
    } catch (err) {
      console.error("mood_logs load failed:", err.message);
      setRecentLogs([]);
    } finally {
      setLoadingLogs(false);
    }
  }
  useEffect(() => { loadRecentLogs(); }, []);

  async function save() {
    await addCravingLog({ id: uid(), patientId: session.id, intensity, tags, createdAt: Date.now() });
    setTags([]); setIntensity(4);
    try {
      await sbInsert("mood_logs", [{ patient_id: session.id, craving_intensity: intensity, triggers: tags }]);
      ctx.toast("تم حفظ التسجيل ✓");
      await loadRecentLogs(); // refresh the real history immediately, not just navigate away blind
      ctx.setView("home");
    } catch (err) {
      console.error("mood_logs insert failed:", err.message);
      ctx.toast(err.message || "تعذّر حفظ التسجيل في القاعدة — حُفظ محليًا فقط", "error");
    }
  }
  return (
    <div>
      <ScreenHeader eyebrow="تتبّع يومي" title="كيف تشعر الآن؟" />
      <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 8 }}>شدّة الرغبة الشديدة: {intensity}/10</div>
      <input type="range" min="0" max="10" value={intensity} onChange={(e) => setIntensity(+e.target.value)} style={{ width: "100%", accentColor: C.ember, marginBottom: 18 }} />
      <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 10 }}>ما الذي أثار هذا الشعور؟</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 22 }}>
        {CRAVING_TAGS.map((t) => (
          <button key={t} onClick={() => toggleTag(t)} className="ss-press" style={{ border: `1.4px solid ${tags.includes(t) ? C.blue : C.border}`, background: tags.includes(t) ? C.blueSoft : "transparent", color: tags.includes(t) ? C.blue : C.textDim, borderRadius: 100, padding: "7px 14px", fontSize: 12.5, cursor: "pointer", fontFamily: FONT }}>{t}</button>
        ))}
      </div>
      <Btn full onClick={save}>حفظ التسجيل</Btn>

      <div style={{ fontWeight: 700, fontSize: 13.5, margin: "26px 0 10px" }}>سجلّك الأخير</div>
      {loadingLogs ? (
        <SkeletonCard />
      ) : !recentLogs || recentLogs.length === 0 ? (
        <EmptyState icon={Activity} title="لا توجد تسجيلات سابقة بعد" sub="سجّلي حالتك اليومية ليبدأ سجلّك بالظهور هنا" />
      ) : (
        <Card>
          {recentLogs.map((l, i) => (
            <div key={l.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 0", borderBottom: i < recentLogs.length - 1 ? `1px solid ${C.borderSoft}` : "none" }}>
              <Pill tone={l.craving_intensity >= 7 ? "ember" : l.craving_intensity >= 4 ? "amber" : "green"}>{l.craving_intensity}/10</Pill>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 11.5 }}>{(l.triggers || []).join("، ") || "بلا مؤثرات محدَّدة"}</div>
                <div style={{ fontSize: 9.5, color: C.textFaint, marginTop: 2 }}>{new Date(l.logged_at).toLocaleString("ar")}</div>
              </div>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

/* =========================================================================
   ROUTER
   ========================================================================= */
function Router({ ctx }) {
  const { session, view } = ctx;

  if (!session) {
    if (view === "splash") return <SplashScreen ctx={ctx} />;
    if (view === "onboarding") return <OnboardingScreen ctx={ctx} />;
    if (view === "roleSelect") return <RoleSelectScreen ctx={ctx} />;
    if (view === "signup") return <SignupScreen ctx={ctx} />;
    if (view === "login") return <LoginScreen ctx={ctx} />;
    return <LandingScreen ctx={ctx} />;
  }

  if (view === "crisis") return <CrisisScreen ctx={ctx} />;
  if (view === "videoCall") return <VideoCallScreen ctx={ctx} />;

  const screens = {
    home: HomeScreen, craving: CravingScreen, specialists: SpecialistsScreen, specialistProfile: SpecialistProfileScreen,
    profile: ProfileScreen, messages: MessagesScreen, chat: ChatScreen, community: CommunityScreen, podcast: PodcastScreen,
    courses: CoursesScreen, courseDetail: CourseDetailScreen, payment: PaymentScreen, booking: BookingScreen,
    search: SearchScreen, notifications: NotificationsScreen, settings: SettingsScreen, calendar: CalendarScreen,
    guardianHome: GuardianHomeScreen, providerHome: ProviderHomeScreen, providerPatients: ProviderPatientsScreen,
    adminHome: AdminHomeScreen, adminUsers: AdminUsersScreen, adminContent: AdminContentScreen,
    recoveryPrograms: RecoveryProgramsScreen, paymentHistory: PaymentHistoryScreen,
  };
  const Screen = screens[view] || HomeScreen;
  return <Shell ctx={ctx}><Screen ctx={ctx} /></Shell>;
}

/* =========================================================================
   ROOT APP
   ========================================================================= */
function useFonts() {
  useEffect(() => {
    if (document.getElementById("staysober-fonts")) return;
    const link = document.createElement("link");
    link.id = "staysober-fonts"; link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Cairo:wght@600;700;800&family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

export default function App() {
  useFonts();
  const [booted, setBooted] = useState(false);
  const [view, setView] = useState("landing");
  const [session, setSession] = useState(null);
  const [pendingRole, setPendingRole] = useState("patient");
  const [activeSpecialist, setActiveSpecialist] = useState(null);
  const [activeCourse, setActiveCourse] = useState(null);
  const [activeConversation, setActiveConversation] = useState(null);
  const [activeAppointment, setActiveAppointment] = useState(null);
  const [viewport, setViewport] = useState(typeof window !== "undefined" && window.innerWidth < 860 ? "mobile" : "desktop");
  const [toast, showToast] = useToast();
  const [unreadCount, setUnreadCount] = useState(NOTIFICATIONS.filter((n) => !n.read).length);

  const [users, setUsers] = useState([]);
  const [cravingLogs, setCravingLogs] = useState([]);
  const [enrollments, setEnrollments] = useState([]);
  const [crisisEvents, setCrisisEvents] = useState([]);
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    (async () => {
      const [u, c, e, x, a] = await Promise.all([
        loadList("staysober2:users"), loadList("staysober2:cravingLogs"), loadList("staysober2:enrollments"),
        loadList("staysober2:crisisEvents"), loadList("staysober2:appointments"),
      ]);
      setUsers(u); setCravingLogs(c); setEnrollments(e); setCrisisEvents(x); setAppointments(a);

      // Real Supabase session restore — if the browser already holds a valid
      // refresh token (from a previous real login), skip straight past the
      // landing/auth screens into the app, just like any real session-aware app.
      try {
        await sbRestoreSession();
        if (sbSession?.user?.email) {
          const rows = await sbSelect("users", { filters: { email: sbSession.user.email }, limit: 1 });
          const dbUser = rows[0];
          if (dbUser) {
            const appRole = DB_ROLE_TO_APP_ROLE[dbUser.role] || "patient";
            setSession({
              id: dbUser.id, name: dbUser.full_name, email: dbUser.email, phone: dbUser.phone,
              role: appRole, wilaya: dbUser.wilaya, verified: dbUser.verified, createdAt: dbUser.created_at, avatar_url: dbUser.avatar_url,
            });
            setView(navFor(appRole)[0].id);
          }
        }
      } catch {
        // No valid session, or SUPABASE_URL/ANON_KEY not yet configured —
        // fall through to the normal landing page, exactly as a first-time
        // visitor would see it. Not a fatal error.
      }

      setBooted(true);
    })();
    function onResize() { setViewport(window.innerWidth < 860 ? "mobile" : "desktop"); }
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  useEffect(() => {
    if (!session?.id) return;
    (async () => {
      try {
        const rows = await sbSelect("notifications", { select: "id", filters: { user_id: session.id, read: false } });
        setUnreadCount(rows.length);
      } catch { /* keeps the mock-derived count as fallback */ }
    })();
  }, [session?.id]);

  const addUser = useCallback(async (u) => setUsers((p) => { const n = [...p, u]; saveList("staysober2:users", n); return n; }), []);
  const addCravingLog = useCallback(async (l) => setCravingLogs((p) => { const n = [l, ...p]; saveList("staysober2:cravingLogs", n); return n; }), []);
  const addEnrollment = useCallback(async (e) => setEnrollments((p) => { const n = [...p, e]; saveList("staysober2:enrollments", n); return n; }), []);
  const addCrisisEvent = useCallback(async (e) => setCrisisEvents((p) => { const n = [e, ...p]; saveList("staysober2:crisisEvents", n); return n; }), []);
  const addAppointment = useCallback(async (a) => setAppointments((p) => { const n = [...p, a]; saveList("staysober2:appointments", n); return n; }), []);

  const ctx = {
    view, setView, session, setSession, pendingRole, setPendingRole, viewport,
    activeSpecialist, setActiveSpecialist, activeCourse, setActiveCourse, activeConversation, setActiveConversation,
    activeAppointment, setActiveAppointment,
    users, addUser, cravingLogs, addCravingLog, enrollments, addEnrollment,
    crisisEvents, addCrisisEvent, appointments, addAppointment,
    toast: showToast, unreadNotifs: unreadCount, setUnreadCount,
  };

  if (!booted) {
    return (
      <>
        <GlobalStyle />
        <div style={{ minHeight: "100vh", background: C.bg, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ width: 32, height: 32, border: `3px solid ${C.border}`, borderTopColor: C.blue, borderRadius: "50%" }} className="ss-spin" />
        </div>
      </>
    );
  }

  return (
    <div dir="rtl" style={{ minHeight: "100vh", background: C.bg, fontFamily: FONT, color: C.text }}>
      <GlobalStyle />
      <Router ctx={ctx} />
      <Toast toast={toast} />
    </div>
  );
}
